export const LANGS = Object.keys(TABLES);
export const RTL_LANGS = ['ar', 'ur'];
/* Languages whose letters join or form conjuncts: their words are never split into single letters for animation. */
export const JOINED = ['ar', 'ur', 'bn', 'hi'];
const ALIAS = { in: 'id', iw: 'he' };

export function pickLang(list) {
  const l = list || (typeof navigator !== 'undefined' ? (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language]) : []);
  for (const raw of l) {
    if (!raw) continue;
    let c = String(raw).toLowerCase().split(/[-_]/)[0];
    c = ALIAS[c] || c;
    if (TABLES[c]) return c;
  }
  return 'en';
}

let lang = pickLang();
export function setLang(code) { if (TABLES[code]) lang = code; }
export const getLang = () => lang;
export const isRtl = () => RTL_LANGS.indexOf(lang) >= 0;
export const isJoined = () => JOINED.indexOf(lang) >= 0;
try { document.documentElement.lang = lang; } catch (e) { /* no document */ }

export function t(key, vars) {
  const tab = TABLES[lang] || TABLES.en;
  let s = tab[key] != null ? tab[key] : (TABLES.en[key] != null ? TABLES.en[key] : key);
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(String(vars[k]));
  return s;
}
